def rep(silhouette, retained, merged, omitted, thin, styles, overlays):
    """🗺️ The eight decisions of one representation."""
    return {"silhouette": silhouette, "retained": retained, "merged": merged, "omitted": omitted, "thinElements": thin, "hatching": t("None: copper, chrome and enamel read by tone, the covers by their darker grey.", "Keine: Kupfer, Chrom und Lack lesen sich über den Ton, die Hauben über ihr dunkleres Grau."), "styles": styles, "overlays": overlays}


